2.     const form = document.getElementById('contact-form');
3.     const statusMessage = document.getElementById('form-status');
4. 
5.     form.addEventListener('submit', (event) => {
6.         event.preventDefault();
7. 
8.         // Clear previous status
9.         statusMessage.textContent = '';
10.         statusMessage.className = '';
11. 
12.         // Basic validation
13.         const fullName = document.getElementById('full-name');
14.         const email = document.getElementById('email');
15.         
16.         let firstInvalidField = null;
17. 
18.         // Reset aria-invalid
19.         [fullName, email].forEach(field => {
20.             field.setAttribute('aria-invalid', 'false');
21.         });
22. 
23.         if (!fullName.value.trim()) {
24.             fullName.setAttribute('aria-invalid', 'true');
25.             if (!firstInvalidField) firstInvalidField = fullName;
26.         }
27. 
28.         if (!email.value.trim() || !email.checkValidity()) {
29.             email.setAttribute('aria-invalid', 'true');
30.             if (!firstInvalidField) firstInvalidField = email;
31.         }
32. 
33.         if (firstInvalidField) {
34.             firstInvalidField.focus();
35.             statusMessage.textContent = 'Please fix the errors in the form before submitting.';
36.             statusMessage.style.color = 'var(--error-color)';
37.             return;
38.         }
39. 
40.         // Simulate successful submission
41.         buttonLoadingState(true);
42. 
43.         setTimeout(() => {
44.             buttonLoadingState(false);
45.             statusMessage.textContent = 'Thank you! Your message has been sent.';
46.             statusMessage.style.color = 'var(--success-color)';
47.             form.reset();
48.         }, 1000);
49.     });
50. 
51.     function buttonLoadingState(isLoading) {
52.         const submitBtn = form.querySelector('button[type="submit"]');
53.         if (isLoading) {
54.             submitBtn.disabled = true;
55.             submitBtn.textContent = 'Sending...';
56.         } else {
57.             submitBtn.disabled = false;
58.             submitBtn.textContent = 'Send Message';
59.         }
60.     }
