         .skip-link {
             position: absolute;
             top: -40px;
             left: 0;
             background: var(--accent-color);
             color: var(--bg-color);
             padding: 8px;
             z-index: 100;
             transition: top 0.3s;
             text-decoration: none;
             font-weight: bold;
         }

         .skip-link:focus {
             top: 0;
             outline: 2px solid var(--focus-outline);
             outline-offset: 2px;
         }

         .container {
             width: 90%;
             max-width: var(--container-width);
             margin: 0 auto;
             padding: var(--spacing) 0;
         }

         header, footer {
             background-color: var(--surface-color);
             padding: 1rem 0;
         }

         h1 {
             font-size: 1.5rem;
         }

         h2 {
             margin-bottom: 0.5rem;
         }

         main {
             flex: 1;
             padding: 2rem 0;
         }

         section {
             background-color: var(--surface-color);
             padding: 2rem;
             border-radius: 8px;
             box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
         }

         .required-notice {
             font-size: 0.875rem;
             color: var(--text-secondary);
             margin-bottom: 1.5rem;
         }

         .form-field {
             margin-bottom: 1.5rem;
         }

         label {
             display: block;
             margin-bottom: 0.5rem;
             font-weight: 600;
         }

         input {
             width: 100%;
             padding: 0.75rem;
             background-color: #2a2a2a;
             border: 1px solid #444;
             border-radius: 4px;
             color: var(--text-primary);
             font-size: 1rem;
             transition: border-color 0.2s, box-shadow 0.2s;
         }

         input:focus {
             outline: none;
             border-color: var(--accent-color);
             box-shadow: 0 0 0 3px rgba(77, 163, 255, 0.3);
         }

         input:focus-visible {
             outline: 2px solid var(--focus-outline);
             outline-offset: 2px;
         }

         .helper-text {
             font-size: 0.875rem;
             color: var(--text-secondary);
             margin-top: 0.25rem;
         }

         .form-actions {
             margin-top: 2rem;
         }

         button {
