 <body>
     <a href="#main-content" class="skip-link">Skip to main content</a>

     <header>
         <div class="container">
             <h1>Support Page</h1>
         </div>
     </header>

     <main id="main-content" class="container">
         <section aria-labelledby="form-heading">
             <h2 id="form-heading">Contact Us</h2>
             <p>Please fill out the form below and our support team will get back to you.</p>
             <p class="required-notice">* indicates required fields</p>

             <form id="contact-form" novalidate>
                 <div class="form-field">
                     <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                     <input type="text" id="full-name" name="full-name" required autocomplete="name" aria-required="true">
                 </div>

                 <div class="form-field">
                     <label for="email">Email Address <span aria-hidden="true">*</span></label>
                     <input type="email" id="email" name="email" required autocomplete="email" aria-required="true">
                 </div>

                 <div class="form-field">
                     <label for="phone">Phone Number (Optional)</label>
                     <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper">
                     <p id="phone-helper" class="helper-text">Format: +1 555-0100 or 555-0100</p>
                 </div>

                 <div class="form-actions">
                     <button type="submit">Send Message</button>
                 </div>

                 <div id="form-status" role="status" aria-live="polite"></div>
             </form>
         </section>
     </main>

     <footer>
         <div class="container">
             <p>&copy; 2026 Support Team</p>
         </div>
     </footer>

     <script>
         document.addEventListener('DOMContentLoaded', () => {
             const form = document.getElementById('contact-form');
             const statusMessage = document.getElementById('form-status');

             form.addEventListener('submit', (event) => {
                 event.preventDefault();

                 // Clear previous status
                 statusMessage.textContent = '';
                 statusMessage.className = '';

                 // Basic validation
                 const fullName = document.getElementById('full-name');
                 const email = document.getElementById('email');

                 let firstInvalidField = null;

                 // Reset aria-invalid
                 [fullName, email].forEach(field => {
                     field.setAttribute('aria-invalid', 'false');
                 });

                 if (!fullName.value.trim()) {
                     fullName.setAttribute('aria-invalid', 'true');
                     if (!firstInvalidField) firstInvalidField = fullName;
                 }

                 if (!email.value.trim() || !email.checkValidity()) {
                     email.setAttribute('aria-invalid', 'true');
                     if (!firstInvalidField) firstInvalidField = email;
                 }

                 if (firstInvalidField) {
                     firstInvalidField.focus();
                     statusMessage.textContent = 'Please fix the errors in the form before submitting.';
                     statusMessage.style.color = 'var(--error-color)';
                     return;
                 }

                 // Simulate successful submission
                 buttonLoadingState(true);

                 setTimeout(() => {
                     buttonLoadingState(false);
                     statusMessage.textContent = 'Thank you! Your message has been sent.';
                     statusMessage.style.color = 'var(--success-color)';
                     form.reset();
                 }, 1000);
             });

             function buttonLoadingState(isLoading) {
                 const submitBtn = form.querySelector('button[type="submit"]');
                 if (isLoading) {
                     submitBtn.disabled = true;
                     submitBtn.textContent = 'Sending...';
                 } else {
                     submitBtn.disabled = false;
                     submitBtn.textContent = 'Send Message';
                 }
             }
         });
     </script>
 </body>
